function cornellNotes(opts){
  opts=opts||{};
  var topic=(opts.topic||'主题').trim()||'主题';
  var cues=String(opts.cues||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# '+topic+' — 康奈尔笔记');
  L.push('');
  L.push('## 线索栏（Cues）');
  if(cues.length){ for(var i=0;i<cues.length;i++) L.push('- '+cues[i]); }
  else { L.push('- （关键词 / 待回答问题）'); }
  L.push('');
  L.push('## 笔记栏（Notes）');
  L.push('- ');
  L.push('');
  L.push('## 总结（Summary）');
  L.push('- （用自己的话写一两句总结）');
  return L.join('\n');
}

var EXPORTS={cornellNotes:cornellNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CornellForgePure = EXPORTS; }
